CREATE TABLE billing_catalog (product_id TEXT NOT NULL, version INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(product_id,version));
CREATE UNIQUE INDEX billing_catalog_active ON billing_catalog(product_id) WHERE active=1;
CREATE TABLE billing_customers (organization_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL, provider_ref TEXT, PRIMARY KEY(organization_id,user_id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE billing_subscriptions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(organization_id,user_id));
CREATE TABLE billing_policies (organization_id TEXT PRIMARY KEY REFERENCES organizations(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE billing_admins (organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(organization_id,user_id));
CREATE TABLE billing_trials (organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(organization_id,user_id));
CREATE TABLE billing_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), event_key TEXT NOT NULL, payload_hash TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL, detail TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), UNIQUE(organization_id,user_id,event_key));
CREATE TABLE billing_invoices (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), period_start TEXT NOT NULL, period_end TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), status TEXT NOT NULL, UNIQUE(organization_id,user_id,period_start));
CREATE TABLE billing_usage (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), feature TEXT NOT NULL, operation_id TEXT NOT NULL, category TEXT NOT NULL, period_start TEXT NOT NULL, quantity REAL NOT NULL CHECK(quantity>=0), status TEXT NOT NULL CHECK(status IN ('reserved','consumed','released')), data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(organization_id,user_id,category,operation_id));
CREATE INDEX billing_usage_period ON billing_usage(organization_id,user_id,period_start,category,status);
CREATE TABLE billing_credit_grants (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), period_start TEXT NOT NULL, category TEXT NOT NULL, quantity REAL NOT NULL CHECK(quantity>0), event_key TEXT NOT NULL, UNIQUE(organization_id,user_id,event_key));
